// 700×700 PNGs of the Kody shirt pattern, densest inside the right edge and
// falling off radially to nothing — one per theme.
//
// The app composes this live: a radial gradient masked by `--kody-pattern`.
// Satori supports neither `mask-image` nor CSS variables, so the mask, the
// tint, and the radial falloff are baked in here. The tint is what makes these
// theme-specific — light ink on the graphite ground, dark ink on the pale one —
// so a theme cannot simply recolour one shared asset. The 430px tile is
// coarser than the app's 340px so the weave survives a feed thumbnail.
// Regenerate from packages/worker/public/images/kody-pattern.png.

const KODY_PATTERN_DARK_BASE64 =
	''

const KODY_PATTERN_LIGHT_BASE64 =
	''

export function getKodyPatternDataUri(theme: 'light' | 'dark'): string {
	const base64 =
		theme === 'light' ? KODY_PATTERN_LIGHT_BASE64 : KODY_PATTERN_DARK_BASE64
	return `data:image/png;base64,${base64}`
}
